{"python":"import re

def truth_label(text):
    m = re.match(r'\s*([A-Z]+)', str(text or ''))
    return m.group(1) if m else None

def extract_table(file, sheet, score_col, truth_col, id_col, max_row=40):
    truth_map = {'NR':0, 'PD':0, 'SD':1, 'PR':1, 'CR':1}
    out = []
    seen = set()
    for r in range(2, max_row + 1):
        try:
            score_raw = cell_ref(file, sheet, r, score_col)
            resp_raw = cell_ref(file, sheet, r, truth_col)
            id_raw = cell_ref(file, sheet, r, id_col)
        except Exception:
            continue
        label = truth_label(resp_raw)
        if score_raw in (None, '') or label not in truth_map:
            continue
        try:
            score = float(score_raw)
        except (TypeError, ValueError):
            continue
        pid = str(id_raw).strip() if id_raw not in (None, '') else f'{sheet}-R{r}'
        key = (pid, score, label)
        if key in seen:
            continue
        seen.add(key)
        out.append({
            'id': pid,
            'score': score,
            'truth': truth_map[label],
            'score_ref': f'{file}/{sheet}/R{r}C{score_col}',
            'truth_ref': f'{file}/{sheet}/R{r}C{truth_col}'
        })
    return out

mibc = extract_table('article.xml', 'Table 1', 5, 6, 2)
biopsy = extract_table('article.xml', 'Table 2', 4, 5, 1)
records_src = mibc + biopsy

records = [{
    'id': r['id'],
    'score': {'ref': r['score_ref']},
    'truth': {'ref': r['truth_ref'], 'map': {'NR':0, 'PD':0, 'SD':1, 'PR':1, 'CR':1}}
} for r in records_src]

negatives = [r for r in records_src if r['truth'] == 0]
tn = sum(1 for r in negatives if r['score'] < 45)
specificity = tn / len(negatives) if negatives else None
complete = len(records_src) == 34 and len(negatives) == 9 and tn == 7
print('MIBC rows:', len(mibc), 'biopsy rows:', len(biopsy), 'total:', len(records_src))
print('negatives:', len(negatives), 'TN:', tn, 'specificity:', specificity)

CONTRACT = {
    'status': 'computed' if complete else 'blocked',
    'fields': {
        'unit': {'value': 'patient', 'evidence': ['article:p34'], 'explanation': 'EVOC results were correlated with clinical data for 34 individual patients.'},
        'platform': {'value': 'organoid', 'evidence': ['article:p4', 'article:p9'], 'explanation': 'The assay is an ex vivo organ culture system preserving tumor slices and their microenvironment.'},
        'readout': {'value': 'viability', 'evidence': ['article:p17'], 'explanation': 'The EVOC score is based on viability, tissue damage, and Ki67 proliferation.'},
        'direction': {'value': 'higher_sensitive', 'evidence': ['article:p34', 'article:p37'], 'explanation': 'Higher EVOC scores indicate greater treatment-induced cancer-cell death and better clinical response.'},
        'threshold_rule': {'value': 'fixed_numeric', 'evidence': ['article:p17', 'article:p37'], 'explanation': 'A fixed EVOC score of 45 separates predicted responders from non-responders.'},
        'threshold_timing': {'value': 'independent_reference', 'evidence': ['article:p17'], 'explanation': 'The threshold was established using a historical MIBC training set, not fitted to the evaluated subjects.'},
        'patient_mapping': {'value': 'individual_available', 'evidence': ['article.xml/Table 1/R1C2', 'article.xml/Table 2/R1C1'], 'explanation': 'Tables 1 and 2 provide patient-level assay scores and clinical outcomes.'},
        'regimen_match': {'value': 'matched', 'evidence': ['article.xml/Table 1/R1C4', 'article.xml/Table 2/R1C3', 'article:p4'], 'explanation': 'The EVOC treatment arm corresponds to the intended therapy subsequently received by each patient.'},
        'n_units': {'value': 34, 'evidence': ['article:p34', 'article:p35'], 'explanation': 'The combined analysis included 16 MIBC resected samples and 18 core-biopsy samples.'},
        'split': {'value': 'independent_test', 'evidence': ['article:p10', 'article:p17'], 'explanation': 'The prospective cohort was tested with a threshold derived from an independent historical training set.'}
    },
    'headline': {
        'metric': 'specificity',
        'reported': specificity if complete else None,
        'reported_evidence': ['article:p34', 'article:p35', 'article:p5'],
        'threshold': 45,
        'op': '>=',
        'score_direction': 'higher',
        'records': records if complete else [],
        'blocked_reason': None if complete else f'Expected 34 records, 9 clinical negatives, and 7 true negatives; found {len(records_src)} records, {len(negatives)} negatives, and {tn} true negatives.'
    },
    'notes': [
        'Specificity is calculated among clinical non-responders (NR or PD) as TN/(TN+FP).',
        'The published specificity is 7/9 = 77.7%.',
        'Clinical responses NR and PD map to truth 0; SD, PR, and CR map to truth 1.'
    ]
}"}
